import re
from datetime import datetime

_GMAIL_DOMAINS = {"gmail.com", "googlemail.com"}
_OPT_OUT_VALUES = {"y", "yes", "true", "1"}
_EXT_MARKER = re.compile(r"ext|x|#", re.IGNORECASE)
_ZIP4 = re.compile(r"^([0-9]+)-[0-9]{4}$")
_FIVE_DIGITS = re.compile(r"^[0-9]{5}$")
_FOUR_DIGITS = re.compile(r"^[0-9]{4}$")
_ANGLE_EMAIL = re.compile(r"<([^<>]*)>")
_TAG_SPLIT = re.compile(r"[;,]")


def _field(row, key):
    """Fetch a field as a string, treating missing/None as ''."""
    value = row.get(key, "")
    return "" if value is None else str(value)


def _normalize_email(raw):
    s = raw
    m = _ANGLE_EMAIL.search(s)
    if m:
        s = m.group(1)
    s = s.strip().lower()
    if s.count("@") == 1:
        local, domain = s.split("@")
        if domain in _GMAIL_DOMAINS:
            local = local.split("+", 1)[0].replace(".", "")
            s = local + "@gmail.com"
    return s


def _is_valid_email(email):
    if email.count("@") != 1:
        return False
    local, domain = email.split("@")
    return (
        local != ""
        and "." in domain
        and not domain.startswith(".")
        and not domain.endswith(".")
    )


def _normalize_phone(raw):
    """Return the 10-digit phone if valid, else ''."""
    s = raw
    m = _EXT_MARKER.search(s)
    if m:
        s = s[: m.start()]
    digits = "".join(ch for ch in s if "0" <= ch <= "9")
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    if len(digits) == 10 and digits[0] not in "01":
        return digits
    return ""


def _normalize_zip(raw):
    s = raw.strip()
    m = _ZIP4.match(s)
    if m:
        s = m.group(1)
    if _FOUR_DIGITS.match(s):
        s = "0" + s
    return s if _FIVE_DIGITS.match(s) else ""


def _normalize_name(raw):
    s = raw.strip()
    if s and (s.isupper() or s.islower()):
        return s.title()
    return s


def _parse_updated(raw):
    s = raw.strip()
    for fmt in ("%Y-%m-%dT%H:%M:%S", "%Y-%m-%d", "%m/%d/%Y"):
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            continue
    raise ValueError(f"Unrecognized 'updated' value: {raw!r}")


def _is_opted_out(raw):
    return raw.strip().lower() in _OPT_OUT_VALUES


def _parse_tags(raw):
    return {t.strip().lower() for t in _TAG_SPLIT.split(raw) if t.strip()}


def dedupe_contacts(rows):
    # ---- Normalize every row; drop rows with no valid email and no valid phone.
    records = []
    for index, row in enumerate(rows):
        email = _normalize_email(_field(row, "email"))
        email = email if _is_valid_email(email) else ""
        phone = _normalize_phone(_field(row, "phone"))
        if not email and not phone:
            continue  # Rule 9
        source = _field(row, "source").strip().lower()
        records.append({
            "index": index,
            "first_name": _normalize_name(_field(row, "first_name")),
            "last_name": _normalize_name(_field(row, "last_name")),
            "email": email,
            "phone": phone,
            "zip": _normalize_zip(_field(row, "zip")),
            "source": source,
            "is_manual": source == "manual",
            "tags": _parse_tags(_field(row, "tags")),
            "opted_out": _is_opted_out(_field(row, "opted_out")),
            "updated": _parse_updated(_field(row, "updated")),
        })

    # ---- Union-find over record positions.
    parent = list(range(len(records)))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            # Keep the root as the earlier record (not required, just tidy).
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb

    first_seen = {}  # match key -> record position
    for pos, rec in enumerate(records):
        keys = []
        if rec["email"]:
            keys.append(("email", rec["email"]))
        last_key = rec["last_name"].lower()
        if rec["phone"] and last_key:
            keys.append(("phone", rec["phone"], last_key))
        for key in keys:
            if key in first_seen:
                union(pos, first_seen[key])
            else:
                first_seen[key] = pos

    # ---- Collect groups.
    groups = {}
    for pos, rec in enumerate(records):
        groups.setdefault(find(pos), []).append(rec)

    def preference(rec):
        # manual first, then most recent updated, then earliest in input
        return (0 if rec["is_manual"] else 1, -rec["updated"].timestamp(), rec["index"])

    def pick(members, field):
        candidates = [r for r in members if r[field]]
        if not candidates:
            return ""
        return min(candidates, key=preference)[field]

    # ---- Build output, ordered by each person's earliest input row.
    ordered = sorted(groups.values(), key=lambda g: min(r["index"] for r in g))
    result = []
    for members in ordered:
        all_tags = set()
        for r in members:
            all_tags |= r["tags"]
        result.append({
            "first_name": pick(members, "first_name"),
            "last_name": pick(members, "last_name"),
            "email": pick(members, "email"),
            "phone": pick(members, "phone"),
            "zip": pick(members, "zip"),
            "source": pick(members, "source"),
            "tags": ";".join(sorted(all_tags)),
            "opted_out": "Y" if any(r["opted_out"] for r in members) else "N",
            "updated": max(r["updated"] for r in members).strftime("%Y-%m-%d"),
        })
    return result
```

Notes on how I read a few edge cases:

- **Datetime comparison:** `-timestamp()` on naive datetimes is safe here because all values share the same (local) interpretation, so the ordering is correct.
- **Extension markers:** The function cuts at the earliest of `ext`, `x`, or `#`. For example, `713-555-0100 ext. 42` and `713-555-0100x42` both become `7135550100`.
- **ZIP+4:** I also accept a ZIP+4 whose leading zero was dropped, such as `2139-4307` → `02139`.
- **Unparseable `updated`:** Since the spec says `updated` is always present, a value in an unknown format raises a `ValueError`. It isn't silently ignored.

**Opt-out caveats.** These follow directly from the rules, but you should check them before sending:
1. Rule 9 drops an opted-out row that has no valid email or phone. That opt-out can't propagate to anyone.
2. Phone-only matching requires a matching non-empty last name. Suppose an opt-out row has a phone but no email and no last name. It won't merge with that person's other rows, so the opt-out won't carry over.

For extra safety, consider building a separate suppression list from **all** opted-out rows' normalized emails and phones. Then exclude any output record that hits that list, regardless of grouping.
